package main

import (
	"path"
	"strings"
)

// matchGlob matches pattern against rel path using doublestar semantics:
// ** matches any number of segments (including zero), * matches within segment, ? matches single char
func matchGlob(pattern, s string) bool {
	// Normalize: remove leading ./ ?
	// Patterns and paths are expected with forward slashes, no leading ./ unless explicit
	// Keep as is
	patSegs := strings.Split(pattern, "/")
	pathSegs := strings.Split(s, "/")
	return matchSegs(patSegs, pathSegs)
}

func matchSegs(pat, s []string) bool {
	// recursive matching with ** support
	if len(pat) == 0 {
		return len(s) == 0
	}
	if pat[0] == "**" {
		// ** matches zero or more segments
		// try match zero
		if matchSegs(pat[1:], s) {
			return true
		}
		// try consume one segment
		for i := 1; i <= len(s); i++ {
			if matchSegs(pat[1:], s[i:]) {
				return true
			}
		}
		return false
	}
	if len(s) == 0 {
		return false
	}
	// match single segment with * ? []
	matched, err := path.Match(pat[0], s[0])
	if err != nil {
		// invalid pattern, fallback to exact?
		if pat[0] != s[0] {
			return false
		}
	} else if !matched {
		return false
	}
	return matchSegs(pat[1:], s[1:])
}

func matchesAny(patterns []string, s string) bool {
	for _, p := range patterns {
		if matchGlob(p, s) {
			return true
		}
	}
	return false
}
