func splitKeyVal(s string) (key, val string, has bool) {
	// find first colon not in quotes
	inSingle := false
	inDouble := false
	for idx, ch := range s {
		if ch == '\'' && !inDouble {
			inSingle = !inSingle
		} else if ch == '"' && !inSingle {
			inDouble = !inDouble
		} else if ch == ':' && !inSingle && !inDouble {
			// check next char is space or end? In YAML, key: value requires space? But allow "key:" with no value
			// For our purposes, split at first colon
			key = strings.TrimSpace(s[:idx])
			val = s[idx+1:]
			return key, val, true
		}
	}
	return strings.TrimSpace(s), "", false
}

func unquote(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= 2 {
		if (s[0] == '\'' && s[len(s)-1] == '\'') || (s[0] == '"' && s[len(s)-1] == '"') {
			return s[1 : len(s)-1]
		}
	}
	return s
}

func stripInlineComment(s string) string {
	inSingle := false
	inDouble := false
	for i, ch := range s {
		if ch == '\'' && !inDouble {
			inSingle = !inSingle
		} else if ch == '"' && !inSingle {
			inDouble = !inDouble
		} else if ch == '#' && !inSingle && !inDouble {
			// check preceding char is space? In YAML, # starts comment only if preceded by space? But simplify: if # not in quotes, strip
			// But need to handle "# comment" vs "a#b" (no space, not comment)? For our patterns, # unlikely in patterns except? We'll require space before #
			if i == 0 || s[i-1] == ' ' || s[i-1] == '\t' {
				return s[:i]
			}
		}
	}
	return s
}

func isInvalidMapping(text string) bool {
	// detect "key: value: ..." with two colons outside quotes where second part looks like value?
	// e.g., "invalid: yaml: ["
	// Count colons outside quotes
	inSingle := false
	inDouble := false
	count := 0
	for _, ch := range text {
		if ch == '\'' && !inDouble {
			inSingle = !inSingle
		} else if ch == '"' && !inSingle {
			inDouble = !inDouble
		} else if ch == ':' && !inSingle && !inDouble {
			count++
		}
	}
	if count >= 2 {
		// check if after first colon, there is another key-like? For "invalid: yaml: [" yes
		return true
	}
	return false
}

func isQuotedContaining(s string, ch byte) bool {
	// check if ch is inside quotes?
	inSingle := false
	inDouble := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\'' && !inDouble {
			inSingle = !inSingle
		} else if c == '"' && !inSingle {
			inDouble = !inDouble
		} else if c == ch && (inSingle || inDouble) {
			return true
		}
	}
	return false
}
