package main

import (
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

var pythonMarkers = []string{"setup.py", "pyproject.toml", "requirements.txt", "poetry.lock", "poetry.toml", ".pylintrc"}

func findPythonRoot(absFile string) string {
	dir := filepath.Dir(absFile)
	return findParentWithFile(dir, pythonMarkers)
}

// parsePythonImports returns list of absolute file paths that are dependencies
func parsePythonFile(absFile, root string) []string {
	data, err := os.ReadFile(absFile)
	if err != nil {
		return nil
	}
	content := string(data)
	// Remove comments? Keep simple: process line by line, handle import/from
	// Need to handle multiline with parentheses and backslash? Simplify: join lines with \ and handle parens
	lines := strings.Split(content, "\n")
	// Preprocess: handle line continuations and parentheses? For simplicity, join lines where parens open?
	// We'll do a simple pass: replace parens/newlines with spaces for import statements?
	// Instead, we'll extract imports via regex on whole content after removing strings/comments? Complex.
	// Simplify: process each line, but also handle "from X import (a, b)" multiline by joining?
	joined := strings.Join(lines, "\n")
	// Find all import statements via regex
	var deps []string
	seen := map[string]bool{}
	addDep := func(abs string) {
		if abs == "" || abs == absFile {
			return
		}
		// only add if file exists and is .py? and not already
		if _, err := os.Stat(abs); err != nil {
			return
		}
		if !strings.HasSuffix(abs, ".py") {
			return
		}
		if !seen[abs] {
			seen[abs] = true
			deps = append(deps, abs)
		}
	}

	// Regex for import and from
	// import a.b.c [as x][, d.e as y]
	// from X import Y
	// We need to handle relative: from . import x, from ..y import z, etc.
	// First, find all "import ..." (but not "from ... import")
	// Use line-based to avoid matching "from" lines twice
	// Split into statements? Handle semicolons? Ignore.

	// Remove string literals? For simplicity, we won't, but imports inside strings are rare. We'll just regex.

	// Handle from imports
	fromRe := regexp.MustCompile(`(?m)^\s*from\s+([.]*)([A-Za-z0-9_\.]*)\s+import\s+([A-Za-z0-9_\*\s,\(\)]+)`)
	// This will match multiline? No, only single line. For multiline with parens, we need to handle.
	// We'll first normalize: replace newlines inside parens with space?
	normalized := normalizePythonParens(joined)
	for _, m := range fromRe.FindAllStringSubmatch(normalized, -1) {
		dots := m[1]
		modPart := m[2]
		importPart := m[3]
		level := len(dots)
		var baseMod string
		if level > 0 {
			// relative
			if modPart != "" {
				baseMod = strings.Repeat(".", level) + modPart
			} else {
				baseMod = strings.Repeat(".", level)
			}
		} else {
			baseMod = modPart
		}
		// importPart may be "(", "a, b", "*", etc. Clean
		importPart = strings.TrimSpace(importPart)
		importPart = strings.Trim(importPart, "() ")
		// split by comma
		names := strings.Split(importPart, ",")
		for _, n := range names {
			n = strings.TrimSpace(n)
			// handle "x as y"
			if strings.Contains(n, " as ") {
				parts := strings.Split(n, " as ")
				n = strings.TrimSpace(parts[0])
			}
			n = strings.TrimSpace(n)
			if n == "" || n == "*" {
				// from X import * -> dependency on X
				abs := resolvePythonModule(baseMod, absFile, root)
				if abs != "" {
					addDep(abs)
				}
				continue
			}
			// Try X/Y as file first
			// baseMod is like "pkg.sub" or ".helper" etc.
			// For "from pkg import helper" where helper is file: X=pkg, Y=helper -> X/Y = pkg/helper.py exists -> edge to file
			// For "from pkg import sub" where sub is package: X/Y = pkg/sub.py doesn't exist (only __init__), so fallback to X
			candidate := baseMod
			if baseMod == "" || baseMod == strings.Repeat(".", level) {
				// e.g., "from . import helper": baseMod=".", Y=helper -> candidate "pkg/helper"?
				// Actually baseMod is "." (level 1, modPart ""), Y=helper -> we want to try currentPackage/helper
				// Our resolve for "X/Y" needs to handle baseMod with dots
				// Construct full module for X/Y
				if level > 0 && modPart == "" {
					// base is package itself, Y is submodule
					// full = relative base + "/" + Y
					fullMod := dotsToModule(dots, modPart, n, absFile, root)
					// Try as file: check if fullMod resolves to .py file (not package __init__? only .py?)
					// For our rule: only check for .py file, not package
					absFileCand := resolvePythonModuleAsFileOnly(fullMod, absFile, root)
					if absFileCand != "" {
						addDep(absFileCand)
					} else {
						// fallback to base (current package)
						absBase := resolvePythonModule(baseMod, absFile, root)
						if absBase != "" {
							addDep(absBase)
						}
					}
				} else {
					// normal: X/Y
					fullMod := baseMod + "." + n
					absFileCand := resolvePythonModuleAsFileOnly(fullMod, absFile, root)
					if absFileCand != "" {
						addDep(absFileCand)
					} else {
						absBase := resolvePythonModule(baseMod, absFile, root)
						if absBase != "" {
							addDep(absBase)
						}
					}
				}
			} else {
				fullMod := baseMod + "." + n
				absFileCand := resolvePythonModuleAsFileOnly(fullMod, absFile, root)
				if absFileCand != "" {
					addDep(absFileCand)
				} else {
					absBase := resolvePythonModule(baseMod, absFile, root)
					if absBase != "" {
						addDep(absBase)
					}
				}
			}
		}
	}

	// Handle plain import: ^\s*import\s+(.+)
	importRe := regexp.MustCompile(`(?m)^\s*import\s+([A-Za-z0-9_\.\s,]+(?:\s+as\s+[A-Za-z0-9_]+)?(?:\s*,\s*[A-Za-z0-9_\.]+(?:\s+as\s+[A-Za-z0-9_]+)?)*)`)
	for _, m := range importRe.FindAllStringSubmatch(normalized, -1) {
		// Avoid matching "from ... import ..." lines: they start with "from", not "import", so safe. But need to ensure not matching inside from? Our regex anchors at line start with optional spaces + "import", so "from" lines won't match.
		listStr := m[1]
		// split by comma, but careful: commas inside? No.
		parts := strings.Split(listStr, ",")
		for _, p := range parts {
			p = strings.TrimSpace(p)
			if strings.Contains(p, " as ") {
				p = strings.TrimSpace(strings.Split(p, " as ")[0])
			}
			p = strings.TrimSpace(p)
			if p == "" {
				continue
			}
			// p is like "pkg.sub.deep" or "os"
			abs := resolvePythonModule(p, absFile, root)
			if abs != "" {
				addDep(abs)
			}
		}
	}
	return deps
}

func normalizePythonParens(s string) string {
	// Replace newlines inside parentheses with space to handle multiline imports
	var out []rune
	depth := 0
	for _, r := range s {
		if r == '(' {
			depth++
		} else if r == ')' {
			if depth > 0 {
				depth--
			}
		}
		if r == '\n' && depth > 0 {
			out = append(out, ' ')
		} else {
			out = append(out, r)
		}
	}
	return string(out)
}

func dotsToModule(dots, modPart, name, absFile, root string) string {
	level := len(dots)
	// compute current package
	pkg := currentPythonPackage(absFile, root)
	// pkg like "pkg.sub" or "pkg" or ""?
	// For level 1, base is pkg; for level 2, parent, etc.
	segs := []string{}
	if pkg != "" {
		segs = strings.Split(pkg, ".")
	}
	// go up level-1? Actually level 1 = current package, so keep all segs; level 2 = parent (drop last), etc.
	if level-1 > len(segs) {
		return ""
	}
	baseSegs := segs[:len(segs)-(level-1)]
	// if modPart != ""? For "from . import helper", modPart="" , name=helper -> baseSegs + [name]
	// For our helper, dots=".", modPart="", name=helper -> we want pkg/helper
	// So full = baseSegs + [name]
	full := append(baseSegs, name)
	return strings.Join(full, ".")
}

func currentPythonPackage(absFile, root string) string {
	rel, _ := filepath.Rel(root, absFile)
	rel = toSlash(rel)
	// e.g., "pkg/sub/reltest.py" or "pkg/__init__.py"
	dir := filepath.Dir(rel)
	dir = toSlash(dir)
	base := filepath.Base(absFile)
	if base == "__init__.py" {
		// package is dir itself: e.g., "pkg/sub" -> "pkg.sub"
		if dir == "." {
			return ""
		}
		return strings.ReplaceAll(dir, "/", ".")
	}
	// otherwise package is dir: e.g., "pkg/sub/reltest.py" -> dir "pkg/sub" -> "pkg.sub"
	if dir == "." {
		return ""
	}
	return strings.ReplaceAll(dir, "/", ".")
}

func resolvePythonModule(mod, absFile, root string) string {
	if mod == "" {
		return ""
	}
	// handle relative with leading dots
	if strings.HasPrefix(mod, ".") {
		level := 0
		for level < len(mod) && mod[level] == '.' {
			level++
		}
		rest := mod[level:]
		pkg := currentPythonPackage(absFile, root)
		var base string
		if pkg == "" {
			if level > 1 {
				return ""
			}
			base = ""
		} else {
			segs := strings.Split(pkg, ".")
			if level-1 > len(segs) {
				return ""
			}
			baseSegs := segs[:len(segs)-(level-1)]
			base = strings.Join(baseSegs, ".")
		}
		var full string
		if rest == "" {
			full = base
		} else {
			if base == "" {
				full = rest
			} else {
				full = base + "." + rest
			}
		}
		if full == "" {
			return ""
		}
		return resolveAbsolutePythonModule(full, root)
	}
	return resolveAbsolutePythonModule(mod, root)
}

func resolveAbsolutePythonModule(mod, root string) string {
	// mod like "pkg.sub.deep" -> try root/pkg/sub/deep.py, then root/pkg/sub/deep/__init__.py
	// also try root/pkg/sub.py? No, for "pkg.sub", that's root/pkg/sub.py or root/pkg/sub/__init__.py?
	// For "pkg", that's root/pkg.py or root/pkg/__init__.py?
	rel := strings.ReplaceAll(mod, ".", "/")
	// try .py
	cand1 := filepath.Join(root, rel+".py")
	if fileExists(cand1) {
		return cand1
	}
	// try __init__.py
	cand2 := filepath.Join(root, rel, "__init__.py")
	if fileExists(cand2) {
		return cand2
	}
	return ""
}

func resolvePythonModuleAsFileOnly(mod, absFile, root string) string {
	// Only check for .py file, not package __init__.py (for from X import Y where Y is file)
	if mod == "" {
		return ""
	}
	var full string
	if strings.HasPrefix(mod, ".") {
		level := 0
		for level < len(mod) && mod[level] == '.' {
			level++
		}
		rest := mod[level:]
		pkg := currentPythonPackage(absFile, root)
		var base string
		if pkg == "" {
			if level > 1 {
				return ""
			}
			base = ""
		} else {
			segs := strings.Split(pkg, ".")
			if level-1 > len(segs) {
				return ""
			}
			baseSegs := segs[:len(segs)-(level-1)]
			base = strings.Join(baseSegs, ".")
		}
		if rest == "" {
			full = base
		} else {
			if base == "" {
				full = rest
			} else {
				full = base + "." + rest
			}
		}
	} else {
		full = mod
	}
	if full == "" {
		return ""
	}
	rel := strings.ReplaceAll(full, ".", "/")
	cand := filepath.Join(root, rel+".py")
	if fileExists(cand) {
		return cand
	}
	return ""
}
