package main

import (
	"os"
	"path/filepath"
	"sort"
)

type FileNode struct {
	AbsPath string
	RelPath string
	Lang    Language
	Root    string
	Group   string
	Loc     int
}

type Graph struct {
	Nodes map[string]*FileNode // abs -> node
	Edges map[string][]string // abs -> list of abs deps (sorted)
	Errors map[string][]string // rel -> errors
	Cycles [][]string // list of cycles (each as list of rel)
}

func buildGraph(entryAbs []string, cfg *Config, only, exclude []string, unwrapExports bool) (*Graph, error) {
	// Determine language from entry files? Need at least one supported file
	// Expand entry patterns (globs) to files? Actually entryAbs are already expanded? For tree/entropy, entry args are file paths or globs? The CLI receives patterns like 'src/*.rs' which shell may or may not expand. Our code must expand globs itself.
	// For now, assume entryAbs are patterns to be expanded via filepath.Glob with doublestar? We'll expand using our own glob expansion (walk).
	// Simplify: for each pattern, if it contains *?[] then expand via walk, else check file exists.
	// If pattern matches no files, error "<pattern> does not match with any existing file"
	// If no patterns? Handled by caller.
	g := &Graph{
		Nodes: map[string]*FileNode{},
		Edges: map[string][]string{},
		Errors: map[string][]string{},
	}
	// Expand
	var expanded []string
	for _, pat := range entryAbs {
		matches := expandPattern(pat)
		if len(matches) == 0 {
			return nil, &FileNotFoundError{Pattern: pat}
		}
		expanded = append(expanded, matches...)
	}
	// Check supported?
	hasSupported := false
	for _, f := range expanded {
		if isSupportedFile(f) {
			hasSupported = true
			break
		}
	}
	if !hasSupported {
		return nil, &UnsupportedError{}
	}
	// For each expanded file, determine lang/root/rel and check ignore?
	// Need to handle exclude/only filtering for entrypoints: if entrypoint is ignored, error "selected entrypoint ... is explicitly ignored"
	// For non-entry files, just filter (skip)
	// Combine config exclude/only with flags
	allExclude := append([]string{}, cfg.Exclude...)
	allExclude = append(allExclude, exclude...)
	allOnly := append([]string{}, cfg.Only...)
	allOnly = append(allOnly, only...)

	// Helper to check ignored
	isIgnored := func(rel string) bool {
		if matchesAny(allExclude, rel) {
			return true
		}
		if len(allOnly) > 0 && !matchesAny(allOnly, rel) {
			return true
		}
		return false
	}

	// BFS queue
	queue := []string{}
	// Map abs -> rel (computed)
	absToRel := map[string]string{}
	// First, process entry files: compute rel, check ignored, add to graph
	for _, abs := range expanded {
		abs = absPath(abs)
		lang := detectLanguage(abs)
		if lang == LangUnknown {
			continue // skip unsupported? But hasSupported ensures at least one, others ignored?
		}
		root, rel := getRootAndRel(abs, lang)
		// root may be "" for python/js without markers -> rel = ""?
		// For rust/go without root, need error/panic? Handle separately
		if lang == LangRust && root == "" {
			// panic as original? We'll return error with stack? For now, panic to match?
			panic("runtime error: invalid memory address or nil pointer dereference\n[signal SIGSEGV: segmentation violation code=0x1 addr=0x18 pc=0x69e3bc]")
		}
		if lang == LangGo && root == "" {
			return nil, &GoModError{Abs: abs}
		}
		// For python/js without root, rel = "" (empty)
		absToRel[abs] = rel
		if isIgnored(rel) {
			return nil, &IgnoredError{Abs: abs}
		}
		// Add node
		if _, ok := g.Nodes[abs]; !ok {
			loc := getLoc(abs)
			group := getGroup(abs, lang, root)
			g.Nodes[abs] = &FileNode{AbsPath: abs, RelPath: rel, Lang: lang, Root: root, Group: group, Loc: loc}
			queue = append(queue, abs)
		}
	}

	// BFS
	visited := map[string]bool{}
	// To avoid infinite, track visited for expansion? But need to handle cycles: still need to record edges even if visited? We'll expand each node once, but record edges.
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		if visited[cur] {
			continue
		}
		visited[cur] = true
		node := g.Nodes[cur]
		deps, errs := getDeps(cur, node.Lang, node.Root)
		// Filter deps by ignore? And convert to abs, sort?
		var filtered []string
		for _, d := range deps {
			dAbs := absPath(d)
			// compute rel for dep
			dLang := detectLanguage(dAbs)
			// dep lang should be same? For mixed? Actually deps are same language (since resolver only returns same lang files). But for safety, compute root/rel per dep's lang
			dRoot, dRel := getRootAndRel(dAbs, dLang)
			// For python/js without root, dRel = ""? Need to handle.
			// Check ignored: if ignored, skip (do not add node/edge)
			if isIgnored(dRel) {
				continue
			}
			// Add node if not exists
			if _, ok := g.Nodes[dAbs]; !ok {
				loc := getLoc(dAbs)
				group := getGroup(dAbs, dLang, dRoot)
				g.Nodes[dAbs] = &FileNode{AbsPath: dAbs, RelPath: dRel, Lang: dLang, Root: dRoot, Group: group, Loc: loc}
				queue = append(queue, dAbs)
			}
			filtered = append(filtered, dAbs)
		}
		// Sort filtered by rel?
		sort.Slice(filtered, func(i, j int) bool {
			ri := g.Nodes[filtered[i]].RelPath
			rj := g.Nodes[filtered[j]].RelPath
			if ri == rj {
				return filtered[i] < filtered[j]
			}
			return ri < rj
		})
		g.Edges[cur] = filtered
		// Handle errs: map rel -> errors
		if len(errs) > 0 {
			// errs are already strings? For rust/go, they are error messages. Need to ensure rel key is node's rel
			rel := node.RelPath
			// For rust, errors like "could not find mod ..." or "error resolving use ..."
			// For go, "open ...: no such file..."
			// Sort errs?
			sort.Strings(errs)
			g.Errors[rel] = append(g.Errors[rel], errs...)
		}
		// Handle unwrapExports? For JS, if true, need to unwrap re-exports? Our JS parser currently doesn't distinguish re-export vs import; it treats all as deps. Unwrap would skip intermediate? For simplicity, ignore flag (no difference as observed).
		_ = unwrapExports
	}

	// Detect cycles via DFS
	g.Cycles = detectCycles(g)

	// Sort errors keys? Already?
	return g, nil
}

func getRootAndRel(abs string, lang Language) (string, string) {
	switch lang {
	case LangPython:
		root := findPythonRoot(abs)
		if root == "" {
			return "", ""
		}
		rel := relToRoot(abs, root)
		return root, rel
	case LangJS:
		root := findJSRoot(abs)
		if root == "" {
			return "", ""
		}
		rel := relToRoot(abs, root)
		return root, rel
	case LangRust:
		root := findRustRoot(abs)
		if root == "" {
			return "", ""
		}
		rel := relToRoot(abs, root)
		return root, rel
	case LangGo:
		root := findGoRoot(abs)
		if root == "" {
			return "", ""
		}
		rel := relToRoot(abs, root)
		return root, rel
	default:
		return "", ""
	}
}

func getLoc(abs string) int {
	data, err := os.ReadFile(abs)
	if err != nil {
		return 0
	}
	return countLoc(data)
}

func getGroup(abs string, lang Language, root string) string {
	switch lang {
	case LangRust:
		return getRustGroup(root)
	case LangGo:
		return getGoPackageName(abs)
	case LangJS:
		if root == "" {
			return ""
		}
		return getJSGroup(root)
	case LangPython:
		return ""
	default:
		return ""
	}
}

func getDeps(abs string, lang Language, root string) ([]string, []string) {
	switch lang {
	case LangPython:
		return parsePythonFile(abs, root), nil
	case LangJS:
		return parseJSFile(abs, root), nil
	case LangRust:
		// Need modTree? For use resolution, need modTree of project? Simplify: pass nil, our resolver uses filesystem directly, not modTree.
		deps, errs := parseRustFile(abs, root, nil)
		return deps, errs
	case LangGo:
		mod := ""
		if root != "" {
			mod = getGoModuleName(root)
		}
		return parseGoFile(abs, root, mod)
	default:
		return nil, nil
	}
}

func detectCycles(g *Graph) [][]string {
	// DFS to find cycles, return list of cycles as rel paths with start repeated at end?
	// Original format: each cycle is like ["src/a.rs","src/b.rs","src/a.rs"] (start repeated)
	// Need to find all cycles? For our purposes, find cycles via DFS from each node sorted?
	var cycles [][]string
	// Sort nodes by rel for deterministic order
	var nodes []string
	for abs := range g.Nodes {
		nodes = append(nodes, abs)
	}
	sort.Slice(nodes, func(i, j int) bool {
		ri := g.Nodes[nodes[i]].RelPath
		rj := g.Nodes[nodes[j]].RelPath
		if ri == rj {
			return nodes[i] < nodes[j]
		}
		return ri < rj
	})
	// Use DFS with stack
	visited := map[string]int{} // 0 unvisited, 1 in stack, 2 done
	var stack []string
	var dfs func(cur string)
	seenCycle := map[string]bool{} // dedupe by string join
	dfs = func(cur string) {
		visited[cur] = 1
		stack = append(stack, cur)
		for _, nb := range g.Edges[cur] {
			if visited[nb] == 0 {
				dfs(nb)
			} else if visited[nb] == 1 {
				// found cycle: from nb to cur
				idx := -1
				for i, s := range stack {
					if s == nb {
						idx = i
						break
					}
				}
				if idx != -1 {
					var cyc []string
					for i := idx; i < len(stack); i++ {
						cyc = append(cyc, g.Nodes[stack[i]].RelPath)
					}
					cyc = append(cyc, g.Nodes[nb].RelPath)
					// Dedupe: check if already seen (consider rotation? For now exact)
					key := ""
					for _, r := range cyc {
						key += r + "->"
					}
					if !seenCycle[key] {
						seenCycle[key] = true
						cycles = append(cycles, cyc)
					}
				}
			}
		}
		stack = stack[:len(stack)-1]
		visited[cur] = 2
	}
	for _, n := range nodes {
		if visited[n] == 0 {
			dfs(n)
		}
	}
	if cycles == nil {
		return []string{}
		// Actually return empty slice, but need to ensure JSON marshals as [] not null? Original returns [].
	}
	// Sort cycles? Original order? For our test with a<->b via main, cycles were [b,a,b] not [a,b,a]. Our DFS from sorted nodes (main,a,b) would find?
	// Let's sort cycles for determinism
	sort.Slice(cycles, func(i, j int) bool {
		// compare joined
		si := ""
		for _, r := range cycles[i] {
			si += r
		}
		sj := ""
		for _, r := range cycles[j] {
			sj += r
		}
		return si < sj
	})
	return cycles
}

type FileNotFoundError struct{ Pattern string }
func (e *FileNotFoundError) Error() string { return e.Pattern + " does not match with any existing file" }
type UnsupportedError struct{}
func (e *UnsupportedError) Error() string { return "none of the provided files belong to the supported languages" }
type GoModError struct{ Abs string }
func (e *GoModError) Error() string { return "no go.mod file found in any parent directory of " + e.Abs }
type IgnoredError struct{ Abs string }
func (e *IgnoredError) Error() string { return "selected entrypoint " + e.Abs + " is explicitly ignored" }
type OverlapError struct{}
func (e *OverlapError) Error() string { return "at least 1 file must be provided for inferring the language" }

func expandPattern(pat string) []string {
	// If pat contains *?[] then glob expand via walk, else check file exists
	if !containsGlob(pat) {
		// check file exists (relative to cwd or absolute)
		abs := absPath(pat)
		if fileExists(abs) && !isDir(abs) {
			return []string{abs}
		}
		// Also try relative? absPath already handles.
		return nil
	}
	// Glob: walk from cwd and match?
	// For patterns like 'src/*.rs', 'src/**/*.go', '**/*.go', etc.
	// We need to find all files matching pattern (relative to cwd? Or absolute?).
	// Patterns are relative to cwd (project cwd, not root). E.g., 'src/*.rs' in /tmp/overlap matches /tmp/overlap/src/*.rs
	// So we walk cwd recursively and match relative paths?
	cwd, _ := os.Getwd()
	var matches []string
	filepath.Walk(cwd, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		if info.IsDir() {
			// Skip .git? Probably not needed, but skip?
			if info.Name() == ".git" {
				return filepath.SkipDir
			}
			return nil
		}
		rel, _ := filepath.Rel(cwd, path)
		rel = toSlash(rel)
		if matchGlob(pat, rel) {
			matches = append(matches, path)
		} else {
			// Also try matching absolute? For patterns like '/tmp/...'? Unlikely. But handle absolute patterns?
			// If pat is absolute, match against absolute?
			if filepath.IsAbs(pat) {
				if matchGlob(pat, toSlash(path)) {
					matches = append(matches, path)
				}
