					}
					if !seenCycle[key] {
						seenCycle[key] = true
						cycles = append(cycles, cyc)
					}
				}
			}
		}
		stack = stack[:len(stack)-1]
		visited[cur] = 2
	}
	for _, n := range nodes {
		if visited[n] == 0 {
			dfs(n)
		}
	}
