type FileNotFoundError struct{ Pattern string }
func (e *FileNotFoundError) Error() string { return e.Pattern + " does not match with any existing file" }
type UnsupportedError struct{}
func (e *UnsupportedError) Error() string { return "none of the provided files belong to the supported languages" }
type GoModError struct{ Abs string }
func (e *GoModError) Error() string { return "no go.mod file found in any parent directory of " + e.Abs }
type IgnoredError struct{ Abs string }
func (e *IgnoredError) Error() string { return "selected entrypoint " + e.Abs + " is explicitly ignored" }
type OverlapError struct{}
func (e *OverlapError) Error() string { return "at least 1 file must be provided for inferring the language" }

func expandPattern(pat string) []string {
	// If pat contains *?[] then glob expand via walk, else check file exists
	if !containsGlob(pat) {
		// check file exists (relative to cwd or absolute)
		abs := absPath(pat)
		if fileExists(abs) && !isDir(abs) {
			return []string{abs}
		}
		// Also try relative? absPath already handles.
		return nil
	}
	// Glob: walk from cwd and match?
	// For patterns like 'src/*.rs', 'src/**/*.go', '**/*.go', etc.
	// We need to find all files matching pattern (relative to cwd? Or absolute?).
	// Patterns are relative to cwd (project cwd, not root). E.g., 'src/*.rs' in /tmp/overlap matches /tmp/overlap/src/*.rs
	// So we walk cwd recursively and match relative paths?
	cwd, _ := os.Getwd()
	var matches []string
	filepath.Walk(cwd, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		if info.IsDir() {
			// Skip .git? Probably not needed, but skip?
			if info.Name() == ".git" {
				return filepath.SkipDir
			}
			return nil
		}
		rel, _ := filepath.Rel(cwd, path)
		rel = toSlash(rel)
		if matchGlob(pat, rel) {
			matches = append(matches, path)
		} else {
			// Also try matching absolute? For patterns like '/tmp/...'? Unlikely. But handle absolute patterns?
			// If pat is absolute, match against absolute?
			if filepath.IsAbs(pat) {
				if matchGlob(pat, toSlash(path)) {
					matches = append(matches, path)
				}
			}
		}
		return nil
	})
	sort.Strings(matches)
	return matches
}

func containsGlob(s string) bool {
	return containsAny(s, "*?[")
}

func containsAny(s, chars string) bool {
	for _, c := range s {
		for _, cc := range chars {
			if c == cc {
				return true
			}
		}
	}
	return false
}
