package main

import (
	"sort"
)

type TreeJSON struct {
	Tree map[string]interface{} `json:"tree"`
	Circular [][]string `json:"circularDependencies"`
	Errors map[string][]string `json:"errors"`
}

func buildTreeJSON(g *Graph, entryAbs string) TreeJSON {
	entryNode, ok := g.Nodes[entryAbs]
	if !ok {
		return TreeJSON{Tree: map[string]interface{}{}, Circular: g.Cycles, Errors: g.Errors}
	}
	visitedPath := map[string]bool{}
	tree := buildTreeRec(g, entryAbs, visitedPath)
	m := map[string]interface{}{entryNode.RelPath: tree}
	errs := g.Errors
	if errs == nil {
		errs = map[string][]string{}
	}
	cyc := g.Cycles
	if cyc == nil {
		cyc = [][]string{}
	}
	return TreeJSON{Tree: m, Circular: cyc, Errors: errs}
}

func buildTreeRec(g *Graph, abs string, path map[string]bool) interface{} {
	if path[abs] {
		return nil
	}
	children := g.Edges[abs]
	if len(children) == 0 {
		return nil
	}
	// If any child is already in path, this node is leaf (don't expand) to match original's truncation
	for _, c := range children {
		if path[c] {
			return nil
		}
	}
	path[abs] = true
	m := map[string]interface{}{}
	for _, c := range children {
		rel := g.Nodes[c].RelPath
		m[rel] = buildTreeRec(g, c, path)
	}
	delete(path, abs)
	_ = sort.StringSlice{}
	return m
}
